/// <summary>
/// This class handles the dialog for modification of Excise Register Entry records
/// </summary>
class METOrderExtractScreenModifyDialog
{
    protected Dialog        dialog;
    protected DialogField   dlgShippingDateConfirmed, dlgRoute, dlgRouteStop;

    private SalesShippingDateConfirmed  shippingDateConfirmed;
    private METRoute                    metRoute;
    private METRouteStop                metRouteStop;
    
}

Method.Source:
   public static void main(Args _args)
   {
       METOrderExtractScreenModifyDialog   dialogOrderExtractScreen;
       SalesTable                          salesTable;
      
       //Check if the Args.Record() has the same TableID as the Table Buffer(SalesTable).
       if (_args.record().TableId == tableNum(SalesTable))
       {
           //Assign the args records to table buffer and then pass it to salesTable_ds(FormDataSource)
           salesTable                  = _args.record();

           //Call Method which will be used to create the Dialog
           dialogOrderExtractScreen  = new METOrderExtractScreenModifyDialog();
           dialogOrderExtractScreen.updateOrderExtractScreenRec(salesTable);
           FormDataSource salesTable_ds = FormDataUtil::getFormDataSource(salesTable);
           salesTable_ds.executeQuery();
       }
   }

    private void updateOrderExtractScreenRec(SalesTable _salesTable)
    {
        dialog = this.dialog(_salesTable);

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            if(this.getFromDialog())
            {
                try
                {
                    ttsbegin;
                    _salesTable.selectForUpdate(true);
  
                    if (_salesTable.METRoute != metRoute)
                    {
                        _salesTable.METRoute = metRoute;
                    }

                    if (_salesTable.METRouteStop != metRouteStop)
                    {
                        _salesTable.METRouteStop = metRouteStop;
                    }

                    if (_salesTable.ShippingDateConfirmed != shippingDateConfirmed)
                    {
                        _salesTable.ShippingDateConfirmed = shippingDateConfirmed;
                    }
                    
                    _salesTable.update();
                    
                    ttscommit;
                    info(StrFmt('Changes have been updated for Sales Id - %1', _salesTable.SalesId));
                }
                catch
                {
                    error('Unexpected error, Please try again or contact System Admin');
                }
                
            }
        }
    }

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <param name = "_salesTable">table record used to set initial values</param>
    /// <returns>The dialog</returns>
   protected Dialog dialog(SalesTable _salesTable)
    {
        //Create a Dialog with title
        dialog = new Dialog('Bulk Update');
        dlgRoute        = dialog.addField(extendedTypeStr(METRoute), 'Route');
        dlgRoute.value(strFmt('%1',_salesTable.METRoute));

        dlgRouteStop   = dialog.addField(extendedTypeStr(metRouteStop), 'Route stop');
        dlgRouteStop.value(strFmt('%1',_salesTable.METRouteStop));

        dlgShippingDateConfirmed  = dialog.addField(extendedTypeStr(SalesShippingDateConfirmed), 'Confirmed shipping date');
        dlgShippingDateConfirmed.value(strFmt('%1',_salesTable.ShippingDateConfirmed));
         
        //Create a "Label" do Dialog
        dialog.addText('Do you wish to proceed?');

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        shippingDateConfirmed   = dlgShippingDateConfirmed.value();
        metRoute                = dlgRoute.value();
        metRouteStop            = dlgRouteStop.value();
        
        return ret;
    }

public static METOrderExtractScreenModifyDialog construct()
{
    return new METOrderExtractScreenModifyDialog();
}
